"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { memoryService } from "@/features/memory/services/memory.service";
import type { Fact, MemoryEvent } from "@/types";

export function useFacts(filters?: Record<string, string>) {
  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["facts", filters],
    queryFn: () => {
      const query = filters?.query || "";
      if (query) {
        return memoryService.search(query, filters);
      }
      return memoryService.getFacts(filters);
    },
  });

  return { 
    facts: data?.data || [], 
    isLoading, 
    error: error instanceof Error ? error.message : null, 
    fetchFacts: refetch 
  };
}

export function useMemoryEvents() {
  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["memoryEvents"],
    queryFn: () => memoryService.getAll(),
  });

  return { 
    events: data?.data || [], 
    isLoading, 
    error: error instanceof Error ? error.message : null, 
    fetchEvents: refetch 
  };
}

export function useStoreMemory() {
  const queryClient = useQueryClient();
  const mutation = useMutation({
    mutationFn: (entry: any) => memoryService.store(entry),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["memoryEvents"] });
      queryClient.invalidateQueries({ queryKey: ["facts"] });
    },
  });

  return { 
    mutate: async (entry: any) => {
      try {
        const result = await mutation.mutateAsync(entry);
        return { data: result.data, error: null };
      } catch (err) {
        return { data: null, error: err instanceof Error ? err.message : "Failed to store memory" };
      }
    },
    isLoading: mutation.isPending
  };
}